func TestJoinSlug(t *testing.T) {
	if got := JoinSlug("Hello World", "Big Day"); got != "hello-world/big-day" {
		t.Errorf("JoinSlug(...) = %q, want %q", got, "hello-world/big-day")
	}
	if got := JoinSlug("a", "", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, empty, b) = %q, want %q", got, "a/b")
	}
	if got := JoinSlug("a", "   ", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, blank, b) = %q, want %q", got, "a/b")
	}
}
